-- Voucher system foundation (spec: tasks/voucher-system-spec-2026-07-30.md rev 3, sections 2, 7.2, 7.3).
-- Seven tables in F11 creation order, updated_at triggers, RLS enabled with no
-- policies (deny-all for anon and authenticated; all access is server-side via the
-- service-role client, which bypasses RLS), private storage bucket, seeds and RBAC.
--
-- Seed literals are generated by scripts/vouchers/extract-voucher-seed.ts from the
-- vendored handoff HTML (docs/design/voucher-system/), never retyped.
-- Ships dark: no UI, no cron; RPCs arrive in 20260802000002 as service-role only.

-- 1. voucher_types (controlled list, migration-seeded; spec 2.1)
create table public.voucher_types (
  id                text primary key,
  display_title     text not null,
  cover_title       text not null,
  value_pence       integer,
  requires_booking  boolean not null,
  alcohol           boolean not null,
  entitlement_html  text not null,
  hero              jsonb not null,
  copy              jsonb not null,
  sort_order        integer not null,
  active            boolean not null default true,
  created_at        timestamptz not null default now(),
  updated_at        timestamptz not null default now()
);

-- 2. terms_versions (spec 2.2; clauses is the ordered [{heading, body}] array)
create table public.terms_versions (
  version        text primary key,
  effective_from date not null,
  clauses        jsonb not null,
  published_by   text,
  created_at     timestamptz not null default now()
);

-- 3. voucher_batches (spec 2.4)
create table public.voucher_batches (
  id                uuid primary key default gen_random_uuid(),
  created_at        timestamptz not null default now(),
  created_by        uuid,                          -- auth user
  created_by_name   text not null,
  note              text,
  terms_version     text not null references public.terms_versions(version),
  type_definitions  jsonb not null,                -- F04 snapshot
  total_count       integer not null,
  pdf_status        text not null default 'pending'
                      check (pdf_status in ('pending','rendering','ready','failed')),
  pdf_path          text,                          -- immutable path incl. render version (F42)
  pdf_bytes         bigint,
  pdf_pages         integer,
  render_attempts   integer not null default 0,
  render_error      text,
  updated_at        timestamptz not null default now()
);

-- 4. voucher_number_counters (spec 2.7)
create table public.voucher_number_counters (
  month_key text primary key,                      -- '2607'
  last_seq  integer not null default 0
);

-- 5. vouchers (spec 2.4)
create table public.vouchers (
  id                  uuid primary key default gen_random_uuid(),
  voucher_number      text not null unique,        -- canonical uppercase 'AN-YYMM-NNNN'
  type_id             text not null references public.voucher_types(id),
  batch_id            uuid not null references public.voucher_batches(id),   -- RESTRICT (default)
  status              text not null check (status in
                        ('generated','issued','redeemed','expired','cancelled','replaced')),
  value_pence         integer,
  terms_version       text not null references public.terms_versions(version),
  -- hand-out
  issued_at           timestamptz,
  issued_by           uuid references public.employees(employee_id) on delete set null,
  issued_by_name      text,
  issued_by_user_id   uuid,                        -- authenticated account that performed it (F29)
  event_id            uuid references public.events(id) on delete set null,
  won_at_label        text,
  expiry_date         date,                        -- REQUIRED at issue (F02), London calendar date
  customer_id         uuid references public.customers(id) on delete set null,
  -- redemption
  redeemed_at         timestamptz,
  redeemed_by         uuid references public.employees(employee_id) on delete set null,
  redeemed_by_name    text,
  redeemed_by_user_id uuid,
  transaction_ref     text,
  booking_ref         text,
  -- lifecycle admin
  cancelled_at        timestamptz,
  cancelled_reason    text,
  replaced_by_id      uuid references public.vouchers(id) on delete set null,
  replaces_id         uuid references public.vouchers(id) on delete set null,
  created_at          timestamptz not null default now(),
  updated_at          timestamptz not null default now(),
  -- lifecycle invariants (F15)
  constraint vouchers_issued_fields check (
    status not in ('issued','redeemed','expired')
    or (issued_at is not null and issued_by_name is not null
        and won_at_label is not null and expiry_date is not null)),
  constraint vouchers_redeemed_fields check (
    status <> 'redeemed' or (redeemed_at is not null and redeemed_by_name is not null)),
  constraint vouchers_cancelled_fields check (
    status not in ('cancelled','replaced') or (cancelled_at is not null and cancelled_reason is not null)),
  constraint vouchers_replaced_link check (
    status <> 'replaced' or replaced_by_id is not null),
  constraint vouchers_no_self_replace check (
    id <> replaced_by_id and id <> replaces_id)
);
create index idx_vouchers_status on public.vouchers (status);
create index idx_vouchers_type_status on public.vouchers (type_id, status);
create index idx_vouchers_batch on public.vouchers (batch_id);
create index idx_vouchers_event on public.vouchers (event_id) where event_id is not null;
create index idx_vouchers_customer on public.vouchers (customer_id) where customer_id is not null;
create index idx_vouchers_status_issued_at on public.vouchers (status, issued_at);
create index idx_vouchers_redeemed_at on public.vouchers (redeemed_at) where redeemed_at is not null;
create index idx_vouchers_expiry_issued on public.vouchers (expiry_date) where status = 'issued';
create unique index uq_vouchers_replaced_by on public.vouchers (replaced_by_id) where replaced_by_id is not null;  -- F14
create unique index uq_vouchers_replaces on public.vouchers (replaces_id) where replaces_id is not null;           -- F14

-- 6. voucher_events (authoritative audit trail; spec 2.4)
create table public.voucher_events (
  id                 uuid primary key default gen_random_uuid(),
  voucher_id         uuid not null references public.vouchers(id),
  action             text not null check (action in
                       ('generated','issued','redeemed','undo_redeem','expired','cancelled',
                        'replaced','reprinted','customer_assigned','customer_removed',
                        'reminder_sent','edited','override_redeemed','note')),
  actor_user_id      uuid,                          -- authenticated account (F43)
  actor_employee_id  uuid,                          -- selected staff member
  actor_name         text not null,                 -- snapshot
  source             text not null check (source in ('management','foh','cron','system')),
  at                 timestamptz not null default now(),
  detail             jsonb                          -- typed per action; customer_id only, never phone/name (F37)
);
create index idx_voucher_events_voucher_at on public.voucher_events (voucher_id, at desc);  -- F38

-- 7. voucher_reminders (F17 outbox)
create table public.voucher_reminders (
  id             uuid primary key default gen_random_uuid(),
  voucher_id     uuid not null references public.vouchers(id),
  customer_id    uuid references public.customers(id) on delete set null,
  reminder_kind  text not null check (reminder_kind in ('day30','day90','pre_expiry')),
  status         text not null default 'pending'
                   check (status in ('pending','sent','skipped','failed','cancelled')),
  scheduled_for  date not null,                     -- London date
  sent_at        timestamptz,
  message_sid    text,
  attempts       integer not null default 0,
  last_error     text,
  created_at     timestamptz not null default now(),
  updated_at     timestamptz not null default now(),
  unique (voucher_id, reminder_kind)
);
create index idx_voucher_reminders_status_scheduled on public.voucher_reminders (status, scheduled_for);

-- updated_at maintenance (reuse existing convention: public.update_updated_at_column()).
create trigger voucher_types_set_updated_at
  before update on public.voucher_types
  for each row execute function public.update_updated_at_column();
create trigger voucher_batches_set_updated_at
  before update on public.voucher_batches
  for each row execute function public.update_updated_at_column();
create trigger vouchers_set_updated_at
  before update on public.vouchers
  for each row execute function public.update_updated_at_column();
create trigger voucher_reminders_set_updated_at
  before update on public.voucher_reminders
  for each row execute function public.update_updated_at_column();

-- RLS (F31): enabled with NO policies on all seven tables. anon and authenticated
-- are denied outright; the service-role client bypasses RLS, and every read/write
-- goes through server code after checkUserPermission. Deliberate deviation from the
-- checklists precedent, which added an explicit (redundant) service_role policy.
do $$
declare t text;
begin
  foreach t in array array[
    'voucher_types','terms_versions','voucher_batches','voucher_number_counters',
    'vouchers','voucher_events','voucher_reminders'
  ] loop
    execute format('alter table public.%I enable row level security;', t);
  end loop;
end $$;

-- Private storage bucket for batch PDFs (F42).
insert into storage.buckets (id, name, public)
values ('vouchers', 'vouchers', false)
on conflict (id) do nothing;

