  ($seed$house-wine$seed$, $seed$BOTTLE OF HOUSE WINE$seed$, $seed$A bottle of house wine$seed$, null, false, true, $seed$<p>This voucher may be exchanged for one 750ml bottle of available house red, white or ros&eacute; still wine. It does not include sparkling wine, Champagne or premium bottled wine.</p><p>Alcohol may only be supplied to someone aged 18 or over, and valid photographic identification may be required.</p>$seed$, $seed${"kind":"word","big":"A bottle","sub":"of house wine"}$seed$::jsonb, $seed${"headline":"Wine not?","script":"You&rsquo;ve clearly earned it","prize":"A bottle of house wine","open":"Uncork this","aside":"Best enjoyed with good people and absolutely no rushing.","community":"Good bottles are better shared."}$seed$::jsonb, 2),
