  ($seed$roast-two$seed$, $seed$SUNDAY ROAST FOR TWO$seed$, $seed$Sunday roast for two$seed$, null, true, false, $seed$<p>This voucher may be exchanged for two standard Sunday roasts from the available Sunday menu.</p><p>It excludes starters, desserts, drinks, additional sides, upgrades and supplements. It is valid during advertised Sunday roast service and is not valid against special menus, private events or separately ticketed occasions unless expressly stated.</p><p>Availability is not guaranteed without an advance booking.</p>$seed$, $seed${"kind":"word","big":"Sunday roast","sub":"for two"}$seed$::jsonb, $seed${"headline":"Sunday plans: sorted","script":"You bring the company, we&rsquo;ll bring the gravy","prize":"Sunday roast for two","open":"Your Sunday starts here","aside":"Two plates. One table. Absolutely no washing up.","community":"Sundays are made for sharing."}$seed$::jsonb, 6),
