INSERT INTO public.terms_versions (version, effective_from, clauses, published_by)
VALUES ($seed$v2.0$seed$, DATE '2026-07-30', $seed$[{"heading":"Voucher entitlement","body":"This voucher may only be used for the entitlement printed on it. It does not provide any entitlement beyond the food, drink, monetary value or event entry specifically stated."},{"heading":"Validity","body":"This voucher is valid at The Anchor, Horton Road, Stanwell Moor Village, Surrey, TW19 6AQ, until close of business on the expiry date shown."},{"heading":"Expiry","body":"The voucher cannot normally be redeemed or extended after its expiry date. Where The Anchor cancels the qualifying event or is unable to provide the stated entitlement before the expiry date, a reasonable alternative or extension will be offered."},{"heading":"Unique voucher number","body":"Each voucher has a unique voucher number and may only be redeemed once. Its validity and redemption status will be checked against The Anchor&rsquo;s voucher system."},{"heading":"Presenting the voucher","body":"A valid printed or authorised digital voucher must be presented to a member of the team before ordering, paying or making the relevant booking."},{"heading":"Single redemption","body":"The voucher must be redeemed in full in one transaction or booking. It cannot be split across multiple transactions, visits or bookings."},{"heading":"Additional payment","body":"Where the total purchase exceeds the voucher&rsquo;s stated value or entitlement, the remaining amount must be paid using an accepted payment method."},{"heading":"Unused value","body":"No change, refund, credit or replacement voucher will be provided where the full monetary value or entitlement is not used."},{"heading":"No cash alternative","body":"The voucher cannot be exchanged for cash, refunded or used to obtain cashback."},{"heading":"Other vouchers and promotions","body":"Only one voucher may be used per transaction or booking. It cannot be combined with another voucher, discount, promotional offer or loyalty reward unless expressly stated."},{"heading":"Excluded purchases","body":"Unless the voucher specifically provides otherwise, it cannot be used towards event tickets, private-hire charges, deposits, gift vouchers, merchandise or any other non-food or non-drink purchase."},{"heading":"Availability and alternatives","body":"All food, drinks and events remain subject to availability. Where the exact item stated is unavailable, The Anchor may offer a reasonable alternative of an equal or greater value. No cash alternative will be provided."},{"heading":"Alcohol and age restrictions","body":"Alcohol may only be supplied to customers aged 18 or over. Valid photographic identification may be required. Customers under 18 may only use an eligible voucher towards non-alcoholic drinks or food."},{"heading":"Responsible service","body":"The supply of alcohol remains subject to licensing law and The Anchor&rsquo;s responsible service policies. The Anchor may refuse to supply alcohol where it would be unlawful or inappropriate to do so."},{"heading":"Event and booking vouchers","body":"Where advance booking is required, the voucher is not considered redeemed until the booking has been confirmed. Once applied to a confirmed booking, changes and cancellations are subject to the normal terms applying to that event."},{"heading":"Invalid vouchers","body":"A voucher will not be accepted where it is expired, altered, illegible, duplicated, already redeemed, replaced, cancelled in the voucher system or otherwise cannot be verified."},{"heading":"Lost or stolen vouchers","body":"Lost or stolen vouchers may only be replaced where the original voucher can be identified, has not been redeemed and can be cancelled in the voucher system. Replacement remains subject to verification."},{"heading":"Resale","body":"Promotional and prize vouchers must not be resold or offered for resale."},{"heading":"Queries and disputes","body":"Any query concerning the validity or redemption of a voucher will be reviewed by a manager against the voucher record, the stated entitlement and these terms."},{"heading":"Terms applying to the voucher","body":"The terms in force when the voucher is issued will apply to that voucher. They will not be changed retrospectively, except where required by law, and no change will reduce the stated entitlement of an already-issued voucher."},{"heading":"Statutory rights","body":"Nothing in these terms affects any statutory rights that cannot legally be excluded."}]$seed$::jsonb, $seed$Design handoff (docs/design/voucher-system)$seed$)
ON CONFLICT (version) DO NOTHING;

-- ---------------------------------------------------------------------------
-- RBAC: the vouchers module (F06, F30).
-- staff + foh_staff: view, edit (FOH surfaces). manager + super_admin: all four.
-- Deputy and portal_shift_manager receive nothing, mirroring the checklists
-- precedent (20260731000000), which granted them nothing either.
-- ---------------------------------------------------------------------------
insert into public.permissions (module_name, action, description) values
  ('vouchers', 'view',   'Look up vouchers and see FOH voucher counts'),
  ('vouchers', 'edit',   'Hand out, redeem and undo-redeem vouchers (FOH)'),
  ('vouchers', 'create', 'Generate voucher batches and print PDFs'),
  ('vouchers', 'manage', 'Full voucher management: ledger, detail, cancel, replace, overrides')
on conflict (module_name, action) do nothing;

-- staff + foh_staff: view, edit.
insert into public.role_permissions (role_id, permission_id)
select r.id, p.id from public.roles r cross join public.permissions p
where r.name in ('staff','foh_staff')
  and p.module_name = 'vouchers' and p.action in ('view','edit')
on conflict do nothing;

-- manager + super_admin: view, edit, create, manage.
insert into public.role_permissions (role_id, permission_id)
select r.id, p.id from public.roles r cross join public.permissions p
where r.name in ('manager','super_admin')
  and p.module_name = 'vouchers'
on conflict do nothing;
